/**
 * The set of top-level keys we allow in a Spectral ruleset. Notably this
 * excludes `functions`, since custom JavaScript functions cannot be executed
 * safely.
 */
const ALLOWED_TOP_LEVEL_KEYS = new Set([
  'extends',
  'rules',
  'documentationUrl',
  'formats',
  'aliases',
  'overrides',
  'parserOptions',
]);

/** Valid Spectral severity strings usable as a rule shorthand. */
const SEVERITY_STRINGS = new Set(['error', 'warn', 'info', 'hint', 'off']);

/** Tokens that could be used for prototype pollution attacks. */
const PROTOTYPE_POLLUTING_TOKENS = ['__proto__', 'prototype', 'constructor'];

/**
 * The built-in Spectral functions we permit in `then.function`. Custom
 * functions are not allowed.
 */
const BUILT_IN_FUNCTIONS = new Set([
  'alphabetical',
  'casing',
  'defined',
  'enumeration',
  'falsy',
  'length',
  'pattern',
  'schema',
  'truthy',
  'typedEnum',
  'undefined',
  'unreferencedReusableObject',
  'or',
  'xor',
]);

/**
 * Normalizes a value to an array: `undefined` becomes an empty array, a single
 * value is wrapped in a one-element array, and arrays are returned unchanged.
 */
export function toArray<T>(value: T | T[] | undefined): T[] {
  if (value === undefined) {
    return [];
  }
  return Array.isArray(value) ? value : [value];
}

type ValidationResult = { isValid: true } | { isValid: false; error: string };

const invalid = (error: string): ValidationResult => ({ isValid: false, error });

const isPlainObject = (value: unknown): value is Record<string, unknown> =>
  typeof value === 'object' && value !== null && !Array.isArray(value);

/**
 * Validates a string `documentationUrl`. Returns an error message when the URL
 * is not an https URL, or `null` when the value is acceptable (including when
 * it is not a string, in which case it is skipped).
 */
const validateDocumentationUrl = (value: unknown): string | null => {
  if (typeof value !== 'string') {
    return null;
  }

  let url: URL;
  try {
    url = new URL(value);
  } catch {
    return 'The "documentationUrl" must be a valid https URL.';
  }

  if (url.protocol !== 'https:') {
    return 'The "documentationUrl" must use the https scheme.';
  }

  return null;
};

/**
 * Validates a single `then` object of a rule (a rule may have one or an array
 * of these). Returns an error message or `null`.
 */
const validateThen = (then: Record<string, unknown>): string | null => {
  const field = then.field;
  if (typeof field === 'string') {
    const hasDisallowedToken = PROTOTYPE_POLLUTING_TOKENS.some(token => field.includes(token));
    const hasPathTraversal = ['.', '[', ']'].some(char => field.includes(char));
    if (hasDisallowedToken || hasPathTraversal) {
      return `The "then.field" value "${field}" contains a disallowed field reference.`;
    }
  }

  if ('function' in then) {
    const fn = then.function;
    if (typeof fn !== 'string' || !BUILT_IN_FUNCTIONS.has(fn)) {
      return `The "then.function" "${String(fn)}" is not an allowed built-in Spectral function.`;
    }
  }

  return null;
};

/**
 * Validates a single rule body. Returns an error message or `null`.
 */
const validateRule = (ruleName: string, ruleBody: unknown): string | null => {
  const bodyIsObject = isPlainObject(ruleBody);

  // Reject prototype-polluting rule names when the body is an object.
  if (bodyIsObject && PROTOTYPE_POLLUTING_TOKENS.includes(ruleName)) {
    return `The rule name "${ruleName}" is not allowed.`;
  }

  const isSeverityShorthand = typeof ruleBody === 'string' && SEVERITY_STRINGS.has(ruleBody);
  if (!bodyIsObject && typeof ruleBody !== 'boolean' && !isSeverityShorthand) {
    return `The rule "${ruleName}" must be an object, boolean, or severity string.`;
  }

  if (!bodyIsObject) {
    return null;
  }

  // Validate `given` expressions for disallowed tokens.
  for (const given of toArray(ruleBody.given as unknown)) {
    if (typeof given !== 'string') {
      // Non-string given values are skipped.
      continue;
    }
    if (PROTOTYPE_POLLUTING_TOKENS.some(token => given.includes(token))) {
      return `The rule "${ruleName}" has a "given" expression containing a disallowed token.`;
    }
  }

  // Validate `then` (may be a single object or an array of objects).
  const thenEntries = toArray(ruleBody.then as unknown);
  for (const then of thenEntries) {
    if (!isPlainObject(then)) {
      // Non-object entries in a `then` array are skipped.
      continue;
    }
    const thenError = validateThen(then);
    if (thenError) {
      return thenError;
    }
  }

  // Per-rule documentationUrl.
  const docError = validateDocumentationUrl(ruleBody.documentationUrl as unknown);
  if (docError) {
    return docError;
  }

  return null;
};

/**
 * Validates the raw contents of a Spectral ruleset file.
 *
 * Returns `{ isValid: true }` for acceptable content, or
 * `{ isValid: false, error }` describing the first problem encountered.
 */
export function validateSpectralRuleset(content: string): ValidationResult {
  if (!content || !content.trim()) {
    return invalid('The ruleset is empty.');
  }

  let parsed: unknown;
  try {
    // JSON is valid YAML, so parsing as YAML also accepts JSON input.
    parsed = YAML.parse(content);
  } catch {
    return invalid('The ruleset could not be parsed as YAML or JSON.');
  }

  if (!isPlainObject(parsed)) {
    return invalid('The ruleset must be an object.');
  }

  const keys = Object.keys(parsed);
  if (keys.length === 0) {
    return invalid('The ruleset must declare at least one of "extends" or "rules".');
  }

  for (const key of keys) {
    if (!ALLOWED_TOP_LEVEL_KEYS.has(key)) {
      return invalid(`Unsupported top-level key "${key}".`);
    }
  }

  if ('extends' in parsed) {
    for (const entry of toArray(parsed.extends as unknown)) {
      if (typeof entry !== 'string') {
        return invalid('All "extends" entries must be strings.');
      }
    }
  }

  if ('rules' in parsed) {
    const rules = parsed.rules;
    if (!isPlainObject(rules)) {
      return invalid('The "rules" must be an object.');
    }

    for (const [ruleName, ruleBody] of Object.entries(rules)) {
      const ruleError = validateRule(ruleName, ruleBody);
      if (ruleError) {
        return invalid(ruleError);
      }
    }
  }

  const topLevelDocError = validateDocumentationUrl(parsed.documentationUrl as unknown);
  if (topLevelDocError) {
    return invalid(topLevelDocError);
  }

  return { isValid: true };
}
