import { isPrivateOrLoopbackHost } from './private-host';
import { toArray, validateSpectralRuleset } from './spectral-ruleset-validator';

/** Maximum depth of nested `extends` chains we will follow. */
const MAX_EXTENDS_DEPTH = 5;

/** Matches the built-in Spectral ruleset identifiers. */
const SPECTRAL_BUILT_IN_RE = /^spectral:(oas|asyncapi|arazzo)$/;

const isSpectralBuiltIn = (entry: string): boolean => SPECTRAL_BUILT_IN_RE.test(entry);

/** A local file path is a relative or absolute filesystem reference. */
const isFilePathEntry = (entry: string): boolean =>
  entry.startsWith('/') || entry.startsWith('./') || entry.startsWith('../') || entry.startsWith('~');

const isYamlFile = (entry: string): boolean => /\.ya?ml$/i.test(entry);

const tryParseUrl = (entry: string): URL | null => {
  try {
    return new URL(entry);
  } catch {
    return null;
  }
};

/** Whether a hostname is an IP literal (and therefore does not need DNS resolution). */
const isIpLiteral = (hostname: string): boolean =>
  /^\d+\.\d+\.\d+\.\d+$/.test(hostname) ||
  hostname.includes(':') ||
  (hostname.startsWith('[') && hostname.endsWith(']'));

const isPlainObject = (value: unknown): value is Record<string, unknown> =>
  typeof value === 'object' && value !== null && !Array.isArray(value);

interface BundledRuleset {
  rules: Record<string, unknown>;
  builtIns: string[];
  remotes: string[];
}

const pushUnique = (list: string[], value: string): void => {
  if (!list.includes(value)) {
    list.push(value);
  }
};

/**
 * Resolves the hostname of a remote extends URL via DNS and throws when any
 * resolved address is private or loopback. IP literals are skipped since they
 * are validated directly by the caller.
 */
const assertRemoteHostIsPublic = async (url: URL): Promise<void> => {
  const hostname = url.hostname;

  if (isPrivateOrLoopbackHost(hostname)) {
    throw new Error(`Remote "extends" points to a disallowed host: ${hostname}`);
  }

  if (isIpLiteral(hostname)) {
    return;
  }

  const resolved = await dns.promises.lookup(hostname, { all: true });
  const addresses = (Array.isArray(resolved) ? resolved : [resolved]).map(entry =>
    typeof entry === 'string' ? entry : entry.address,
  );

  for (const address of addresses) {
    if (isPrivateOrLoopbackHost(address)) {
      throw new Error(
        `Remote "extends" hostname "${hostname}" resolves to a private or loopback address: ${address}`,
      );
    }
  }
};

/**
 * Fetches, validates, and recursively checks a remote ruleset referenced from
 * an `extends` entry. Remote rule content is never merged into the bundle — the
 * URL is preserved verbatim — but the ruleset must pass validation and its own
 * nested remote extends are checked as well.
 */
const validateRemoteExtends = async (rawUrl: string, url: URL, depth: number): Promise<void> => {
  if (depth > MAX_EXTENDS_DEPTH) {
    throw new Error('The "extends" chain is nested too deeply.');
  }

  if (url.protocol !== 'https:') {
    throw new Error('Remote "extends" URL must use https:');
  }

  await assertRemoteHostIsPublic(url);

  const response = await fetch(rawUrl);
  if (!response.ok) {
    throw new Error(`Failed to fetch remote ruleset "${rawUrl}" (status ${response.status}).`);
  }

  const text = await response.text();
  const result = validateSpectralRuleset(text);
  if (!result.isValid) {
    throw new Error(
      `Invalid Spectral ruleset: remote extends "${rawUrl}" failed validation: ${result.error}`,
    );
  }

  // Recursively check any nested remote extends declared by the remote ruleset.
  const parsed = YAML.parse(text);
  if (isPlainObject(parsed)) {
    for (const nested of toArray(parsed.extends as unknown)) {
      if (typeof nested !== 'string' || isSpectralBuiltIn(nested)) {
        continue;
      }
      const nestedUrl = tryParseUrl(nested);
      if (nestedUrl) {
        await validateRemoteExtends(nested, nestedUrl, depth + 1);
      }
